ode": {"@listName": "exclusion-ground", "#text": "envir-law"}}, {"cbc:TendererRequirementTypeCode": {"@listName": "exclusion-ground", "#text": "finan-laund"}}, {"cbc:TendererRequirementTypeCode": {"@listName": "exclusion-ground", "#text": "fraud"}}, {"cbc:TendererRequirementTypeCode": {"@listName": "exclusion-ground", "#text": "human-traffic"}}, {"cbc:TendererRequirementTypeCode": {"@listName": "exclusion-ground", "#text": "insolvency"}}, {"cbc:TendererRequirementTypeCode": {"@listName": "exclusion-ground", "#text": "labour-law"}}, {"cbc:TendererRequirementTypeCode": {"@listName": "exclusion-ground", "#text": "liq-admin"}}, {"cbc:TendererRequirementTypeCode": {"@listName": "exclusion-ground", "#text": "misrepresent"}}, {"cbc:TendererRequirementTypeCode": {"@listName": "exclusion-ground", "#text": "nati-ground"}}, {"cbc:TendererRequirementTypeCode": {"@listName": "exclusion-ground", "#text": "partic-confl"}}, {"cbc:TendererRequirementTypeCode": {"@listName": "exclusion-ground", "#text": "prep-confl"}}, {"cbc:TendererRequirementTypeCode": {"@listName": "exclusion-ground", "#text": "prof-misconduct"}}, {"cbc:TendererRequirementTypeCode": {"@listName": "exclusion-ground", "#text": "sanction"}}, {"cbc:TendererRequirementTypeCode": {"@listName": "exclusion-ground", "#text": "socsec-law"}}, {"cbc:TendererRequirementTypeCode": {"@listName": "exclusion-ground", "#text": "socsec-pay"}}, {"cbc:TendererRequirementTypeCode": {"@listName": "exclusion-ground", "#text": "susp-act"}}, {"cbc:TendererRequirementTypeCode": {"@listName": "exclusion-ground", "#text": "tax-pay"}}, {"cbc:TendererRequirementTypeCode": {"@listName": "exclusion-ground", "#text": "terr-offence"}}]}}, "cac:TenderingProcess": {"cbc:ProcedureCode": {"@listName": "procurement-procedure-type", "#text": "neg-w-call"}, "cac:ProcessJustification": {"cbc:ProcessReasonCode": {"@listName": "accelerated-procedure", "#text": "false"}}}, "cac:ProcurementProject": {"cbc:ID": "25TX088", "cbc:Name": {"@languageID": "FRA", "#text": "Fourniture et pose de canalisations d'eau potable et des prises en charge des branchements à l'Ile d'Yeu"}, "cbc:Description": {"@languageID": "FRA", "#text": "La présente consultation concerne la fourniture et la pose de canalisations d'eau potable et des prises en charge des branchements à l'Ile d'Yeu (rues de la Filière, de Belle-Poule, Pierre Henry, de la Grouille, de la Chapelle, de la Chartreuse et du Champ de Foire)."}, "cbc:ProcurementTypeCode": {"@listName": "contract-nature", "#text": "works"}, "cbc:Note": {"@languageID": "FRA", "#text": "La présente consultation est passée sous la forme d'une procédure avec négociation. La première étape consiste en la remise par les candidats intéressés de leur dossier de candidature. Les candidats pourront trouver de plus amples informations dans le règlement de consultation - phase candidature disponible gratuitement sur le profil acheteur de Vendée Eau : www.marches-securises.fr Une fois les candidats admis à remettre une offre, suivra une deuxième étape relative à la remise des offres. Les candidats retenus recevront le dossier de consultation via le profil acheteur de Vendée Eau. A ce titre, les candidats sont avertis qu'il est crucial de renseigner dans leur profil sur la plateforme marches-sécurisés une adresse mail valide et régulièrement consultée."}, "cac:MainCommodityClassification": {"cbc:ItemClassificationCode": {"@listName": "cpv", "#text": "45231300"}}, "cac:RealizedLocation": {"cbc:Description": {"@languageID": "FRA", "#text": "Il s'agit d'une procédure avec négociation (Articles L.2124-3 et R.2124-4 du Code de la Commande Publique). Elle comprend 2 phases : 
- une phase « Candidature » : à ce stade, les candidats adressent uniquement les pièces de la candidature ; 
o l'entité adjudicatrice arrête la liste des candidats admis aux négociations, après examen des candidatures ; 
o les candidats admis sont invités à remettre leur offre ; 
- une phase « Offre » : 
